Here is the root cause:
The bug was caused by the use of the incorrect configuration check `CONFIG_DEBUG_HIGHMEM` instead of `CONFIG_DEBUG_KMAP_LOCAL` in the functions `__kmap_local_sched_out()` and `__kmap_local_sched_in()`. This led to guard pages not being correctly skipped when `DEBUG_KMAP_LOCAL_FORCE_MAP` was enabled, resulting in potential memory management issues.

Here is the patch:
  */
 void __kmap_local_sched_out(void)
 {
 	struct task_struct *tsk = current;
 	pte_t *kmap_pte = kmap_get_pte();
 	int i;

 	/* Clear kmaps */
 	for (i = 0; i < tsk->kmap_ctrl.idx; i++) {
 		pte_t pteval = tsk->kmap_ctrl.pteval[i];
 		unsigned long addr;
 		int idx;

 		/* With debug all even slots are unmapped and act as guard */
-		if (IS_ENABLED(CONFIG_DEBUG_HIGHMEM) && !(i & 0x01)) {
+		if (IS_ENABLED(CONFIG_DEBUG_KMAP_LOCAL) && !(i & 0x01)) {
 			WARN_ON_ONCE(!pte_none(pteval));
 			continue;
 		}
 		if (WARN_ON_ONCE(pte_none(pteval)))
 			continue;

 		/*
 		 * This is a horrible hack for XTENSA to calculate the
 		 * coloured PTE index. Uses the PFN encoded into the pteval
 		 * and the map index calculation because the actual mapped
 		 * virtual address is not stored in task::kmap_ctrl.
 		 * For any sane architecture this is optimized out.
 		 */
 		idx = arch_kmap_local_map_idx(i, pte_pfn(pteval));

 		addr = __fix_to_virt(FIX_KMAP_BEGIN + idx);
 		arch_kmap_local_pre_unmap(addr);
 		pte_clear(&init_mm, addr, kmap_pte - idx);
 		arch_kmap_local_post_unmap(addr);
 	}
 }

 void __kmap_local_sched_in(void)
 {
 	struct task_struct *tsk = current;
 	pte_t *kmap_pte = kmap_get_pte();
 	int i;

 	/* Restore kmaps */
 	for (i = 0; i < tsk->kmap_ctrl.idx; i++) {
 		pte_t pteval = tsk->kmap_ctrl.pteval[i];
 		unsigned long addr;
 		int idx;

 		/* With debug all even slots are unmapped and act as guard */
-		if (IS_ENABLED(CONFIG_DEBUG_HIGHMEM) && !(i & 0x01)) {
+		if (IS_ENABLED(CONFIG_DEBUG_KMAP_LOCAL) && !(i & 0x01)) {
 			WARN_ON_ONCE(!pte_none(pteval));
 			continue;
 		}
 		if (WARN_ON_ONCE(pte_none(pteval)))
 			continue;

 		/* See comment in __kmap_local_sched_out() */
 		idx = arch_kmap_local_map_idx(i, pte_pfn(pteval));
 		addr = __fix_to_virt(FIX_KMAP_BEGIN + idx);
 		set_pte_at(&init_mm, addr, kmap_pte - idx, pteval);
 		arch_kmap_local_post_map(addr, pteval);
 	}
 }



